head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


include("../js/libRoundPanel.js");
include("../js/utils.js");
include("../js/session.js");
include("../js/PopupCalendar.js");
include("../js/stf.js");
scwin.vScrenID = 'ULDSTF71002_P.gfm';
scwin.vCurDate = cGetToday("yyyymmdd");
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
}; // 오늘날짜


//부모창에서 필요변수 저장
scwin.fn_GetParentValue = function() {
    gSEQ = frame.opener.gSEQ;
    gDESIGN_ADVSER_ISUR_CD = frame.opener.gDESIGN_ADVSER_ISUR_CD;
    gDESIGN_ADVSER_COM_ABBRV = frame.opener.gDESIGN_ADVSER_COM_ABBRV;
    gADVCE_COM_ISUR_CD = frame.opener.gADVCE_COM_ISUR_CD;
    gADVCE_COM_ABBRV = frame.opener.gADVCE_COM_ABBRV;
    gADVCE_COM_APPL_TP_NM = frame.opener.gADVCE_COM_APPL_TP_NM;
    gADVCE_COM_APPL_TP_CD = frame.opener.gADVCE_COM_APPL_TP_CD;
    gAPPL_REQ_DD = frame.opener.gAPPL_REQ_DD;
    gSTRT_DD = frame.opener.gSTRT_DD;
    gADVCE_COM_PROCS_STAT_NM = frame.opener.gADVCE_COM_PROCS_STAT_NM;
    gADVCE_COM_PROCS_STAT_CD = frame.opener.gADVCE_COM_PROCS_STAT_CD;
    gCONTRT_DD = frame.opener.gCONTRT_DD;
    gRELEAS_DD = frame.opener.gRELEAS_DD;
    gREVWR_NM = frame.opener.gREVWR_NM;
    gAPPROVR_NM = frame.opener.gAPPROVR_NM;
    gAPPROV_DDTM = frame.opener.gAPPROV_DDTM;
    gEMP_NM = frame.opener.gEMP_NM;
    gDEP_NM = frame.opener.gDEP_NM;
};



//초기화
scwin.fn_Init = function() {
    showObj(tbx_seq, false); // SEQ hidden
    showObj(tbx_seq_real, false); // SEQ hidden

    if ((gADVCE_COM_PROCS_STAT_CD == "1")) {
        // 미처리(1)  >  검토(2), 거부(4)단계
        showObj(btn_Study, true); // 검토버튼
        showObj(btn_Approv, false); // 승인버튼		
        showObj(label_13, false); // 설명문구
    } else if (gADVCE_COM_PROCS_STAT_CD == "2") {
        // 검토(2) > 승인(3), 거부(4) 단계
        showObj(btn_Study, false); // 검토버튼

        if (js_jobtitl == "09") {
            // 팀장 > 승인(3)/거부(4) 가능
            showObj(btn_Approv, true); // 승인버튼				
            showObj(label_13, false); // 설명문
        } else {
            // 팀원 > 거부(4) 가능
            showObj(btn_Approv, false); // 승인버튼			
            showObj(label_13, true); // 설명문
        }
    } else {
        showObj(btn_Study, false); // 검토버튼
        showObj(btn_Approv, false); // 승인버튼	
        showObj(label_13, false); // 설명문
    }
    tbx_seq_real.setValue(gSEQ); //PK 히든객체에 저장

    tbx_1.setValue(" " + gDESIGN_ADVSER_ISUR_CD);
    tbx_2.setValue(" " + gDESIGN_ADVSER_COM_ABBRV);
    tbx_3.setValue(" " + gADVCE_COM_ISUR_CD);
    tbx_4.setValue(" " + gADVCE_COM_ABBRV);
    tbx_5.setValue(" " + gADVCE_COM_APPL_TP_NM);
    tbx_6.setValue(" " + com.wconv.subStr(0, 4) + "년 " + com.wconv.subStr(4, 2) + "월 " + com.wconv.subStr(6, 2) + "일");
    tbx_7.setValue(" " + gADVCE_COM_PROCS_STAT_NM);
    setObjectValue(edt_ToDate, gSTRT_DD); // 적용일자 값 채우기


    // 가우스헤더 셋팅
    dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DIGITAL_DESIGN_ADVICE_APPL_PROCS_UPDATE_INOUT";
    dts_MASTER.reset();
    dts_MASTER.insertRow();
};




//데이터셋 초기화
scwin.fn_InitDts = function() {
    var url = "/digital/Digitalissueinfo.do?method=getDigitalDesignAdviceApplProcsInit";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.reset();
};



//검토
scwin.fn_study = function() {
    if (getObjectValue(edt_ToDate) == "") {
        alert("적용일자 항목을 입력하십시요");
        return false;
    }

    /*	if(getObjectValue(edt_ToDate) <= vCurDate){
    		alert("적용일자는 오늘 이후의 날짜만 입력 가능합니다.");
    		return false;
    	}*/


    var rtn = confirm('검토처리 하시겠습니까?');
    var vSeq = getObjectValue(tbx_seq_real);
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_MASTER.NameValue(1, "SEQ") = vSeq; //SEQ*/
        X = vSeq; //SEQ

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_MASTER.NameValue(1, "REVWR_ID") = js_id; //검토자ID*/
        X = js_id; //검토자ID

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_MASTER.NameValue(1, "APPROVR_ID") = ""; //승인자ID*/
        X = ""; //승인자ID

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_MASTER.NameValue(1, "ADVCE_ISU_PROCS_STAT_CD") = "2"; //상태코드 (검토2)*/
        X = "2"; //상태코드 (검토2)

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_MASTER.NameValue(1, "ADVCE_ISU_APPL_TP_CD") = gADVCE_COM_APPL_TP_CD; // 신청구분코드(추가 or 해제)*/
        X = gADVCE_COM_APPL_TP_CD; // 신청구분코드(추가 or 해제)

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_MASTER.NameValue(1, "STRT_DD") = getObjectValue(edt_ToDate); //적용일자(사용자입력 값)*/
        X = getObjectValue(edt_ToDate); //적용일자(사용자입력 값)


        var url = "/digital/Digitalissueinfo.do?method=procDigitalDesignAdviceApplProcs";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_inquiry.Post();
    }
};




