scwin.trs_inquiry_OnSuccess = function() {
    alert("성공적으로 처리 되었습니다.");
    frame.CloseFrame();
    // 부모창 reload 처리해야함	
    frame.Provider("../").fn_Search();
};
scwin.trs_inquiry_OnFail = function() {
    alert('trs_inquiry.OnFail() :' + trs_inquiry.ErrorMsg);
};
scwin.btn_Close_onclick = function(e) {
    frame.CloseFrame();
};
scwin.btn_Approv_onclick = function(e) {
    scwin.fn_approv();
};
scwin.gform_onload = function() {
    scwin.fn_GetParentValue();
    scwin.fn_Init();
    scwin.fn_InitDts();
    doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
};
scwin.img_ToCal_onclick = function(e) {
    popUpCalendar2(edt_ToDate);
};
scwin.btn_Study_onclick = function(e) {
    scwin.fn_study();
};
